const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[80,"A",0,1],[112,"A",0,1],[144,"A",0,1],[176,"REST",0,1],[208,"REST",0,1],[224,"A",0,1],[256,"A",0,1],[288,"A",0,2]]
